//#region src/types.d.ts
/** The commit author */
interface GitCommitAuthor {
  /** The author name */
  name: string;
  /** The author email */
  email: string;
}
/** The raw git commit */
interface RawGitCommit {
  /** The commit message */
  message: string;
  /** The commit body */
  body: string;
  /** The commit hash */
  shortHash: string;
  /** The commit author */
  author: GitCommitAuthor;
}
/** The reference of the commit */
interface Reference {
  /** The reference type */
  type: 'hash' | 'issue' | 'pull-request';
  /** The reference value */
  value: string;
}
/** The resolved github author */
interface ResolvedAuthor extends GitCommitAuthor {
  /** The git commit of the author */
  commits: string[];
  /** The github logged username of the author */
  login: string;
}
/** Git commit config */
interface GitCommit extends RawGitCommit {
  /** The commit description */
  description: string;
  /** The commit scope type */
  type: string;
  /** The commit scope */
  scope: string;
  /** The commit references */
  references: Reference[];
  /** The commit authors */
  authors: GitCommitAuthor[];
  /** The resolved authors */
  resolvedAuthors: ResolvedAuthor[];
  /** The commit breaking changes */
  isBreaking: boolean;
}
/** Github config */
interface GithubConfig {
  /**
   * The github repository name
   *
   * @example
   *   soybeanjs / changelog;
   */
  repo: string;
  /** The github token */
  token: string;
}
/**
 * How to resolve the `from` tag when generating a stable release changelog
 *
 * - `last-stable`: aggregate all changes since the previous stable release, including all prerelease changes
 * - `last-tag`: only the changes since the previous tag, without duplicating prerelease sections
 * - `last-prerelease`: only the changes since the final same-line prerelease (e.g. the final rc)
 */
type FromStrategy = 'last-stable' | 'last-tag' | 'last-prerelease';
interface ChangelogOption {
  /**
   * The directory of the project
   *
   * @default process.cwd()
   */
  cwd: string;
  /** The commit scope types */
  types: Record<string, string>;
  /** Github config */
  github: GithubConfig;
  /** The commit hash or tag */
  from: string;
  /** The commit hash or tag */
  to: string;
  /** The whole commit tags */
  tags: string[];
  /** The commit tag and date map */
  tagDateMap: Map<string, string>;
  /** Whether to capitalize the first letter of the commit type */
  capitalize: boolean;
  /**
   * Use emojis in section titles
   *
   * @default true
   */
  emoji: boolean;
  /** The section titles */
  titles: {
    /** The title of breaking changes section */
    breakingChanges: string;
  };
  /** The output file path of the changelog */
  output: string;
  /**
   * Whether to regenerate the changelog if it already exists
   *
   * @example
   *   the changelog already exists the content of v0.0.1, but you want to regenerate it
   */
  regenerate: boolean;
  /** Mark the release as prerelease */
  prerelease?: boolean;
  /**
   * How to resolve the `from` tag when generating a stable release changelog
   *
   * - `last-stable`: aggregate all changes since the previous stable release, including all prerelease changes (default)
   * - `last-tag`: only the changes since the previous tag, without duplicating prerelease sections
   * - `last-prerelease`: only the changes since the final same-line prerelease (e.g. the final rc)
   *
   * @default 'last-stable'
   */
  fromStrategy?: FromStrategy;
}
//#endregion
//#region src/version.d.ts
/** The parsed semantic version info */
interface ParsedVersion {
  /** The normalized version with `v` prefix, e.g. `v1.2.3-beta.1` */
  raw: string;
  /** The core version without prerelease part, e.g. `1.2.3` */
  core: string;
  /** Whether it is a stable version (no prerelease identifier) */
  stable: boolean;
  /** The prerelease channel, e.g. `alpha`, `beta`, `rc`, empty for stable versions */
  channel: string;
  /** The prerelease sequence number, `0` for stable versions */
  seq: number;
}
/**
 * Parse a version tag into structured info
 *
 * Supports any semver prerelease channel (`alpha`, `beta`, `rc`, `canary`, `next`, ...)
 *
 * @param version The version tag, with or without `v` prefix
 * @returns The parsed version info, or null if the input is not a valid semver version
 *
 * @example
 *   parseVersion('v1.2.3-rc.1');
 *   // => { raw: 'v1.2.3-rc.1', core: '1.2.3', stable: false, channel: 'rc', seq: 1 }
 */
export declare function parseVersion(version: string): ParsedVersion | null;
/**
 * Check whether the input is a valid semver version
 *
 * @param version The version tag, with or without `v` prefix
 */
export declare function isValidVersion(version: string): boolean;
/**
 * Check whether the version is a prerelease
 *
 * Non-version strings (e.g. branch names like `main`) are treated as prereleases
 *
 * @param version The version tag or ref name
 */
export declare function isPrerelease(version: string): boolean;
//#endregion
